70	    // DMCONTROL bit is honored (RISC-V Debug Spec).
71	    bus_.write(kDmcontrol, kDmcontrolDmactive);
72	    request_halt();
73	    poll_until_set(bus_, kDmstatus, kDmstatusAllhalted, "ResumeDriver halt");
