94	    // FPR restore (requires mstatus.FS enabled above): one abstract register
95	    // write per f-reg, abstract-only by design like every non-V register
96	    // block. Minimal slice: only f0 -- f1..f31 and fcsr land in the FP
97	    // completion commit.
98	    if (state.flags & HYBRID_FLAG_FP)
