132	  // Abstract-first CSR write with Program Buffer fallback.
133	  // Tries an abstract register write; if the DM signals cmderr, clears it,
134	  // stages the value in scratch_gpr via abstract GPR write, then executes a
135	  // one-instruction PB (`csrrw x0, csr, scratch_gpr`).  scratch_gpr defaults
136	  // to x5 (t0) which the GPR restore loop overwrites later.
137	  void write_csr_abstract_or_pb(uint16_t csr, uint64_t value,
138	                                 uint8_t scratch_gpr = 5)
139	  {
140	    write_64bit_register(regno_csr(csr), value);
141	    if ((bus_.read(kAbstractcs) & kAbstractcsCmderrMask) == 0u) return;
142	    bus_.write(kAbstractcs, kAbstractcsCmderrMask);  // W1C: clear sticky error
143	    write_64bit_register(regno_gpr(scratch_gpr), value);
144	    const std::array<uint32_t, 1> pb = { encode_csrrw(0, csr, scratch_gpr) };
145	    exec_progbuf(bus_, std::span<const uint32_t>{pb});
146	  }
147	
148	  // abstractcs.cmderr is sticky per the Debug Spec - a subsequent command
149	  // is rejected until the bits are W1C-cleared. We tolerate per-register
150	  // failures (e.g. unimplemented FPR/CSR Abstract access) by clearing the
151	  // error before resuming so the hart isn't left in a stuck state.
152	  // B17: record the last observed non-zero cmderr and a clear count so a
153	  // partially-broken restore is observable via the public accessors
154	  // instead of silently swallowed.
155	  void clear_cmderr_if_set()
156	  {
157	    const auto status = bus_.read(kAbstractcs);
158	    const auto code = (status & kAbstractcsCmderrMask) >> 8;
159	    if (code != 0u) {
160	      last_observed_cmderr_ = code;
161	      ++cmderr_clear_count_;
162	      bus_.write(kAbstractcs, kAbstractcsCmderrMask);
163	    }
164	  }
165	
166	  DmiBus& bus_;
167	  uint32_t last_observed_cmderr_ = 0;
168	  uint64_t cmderr_clear_count_   = 0;
169	
170	public:
171	  // B17: diagnostic side channel. Non-zero last_observed_cmderr() means
172	  // at least one abstract write tripped a sticky cmderr the restore
173	  // tolerated by clearing. cmderr_clear_count() is the total number of
174	  // such clears across all calls into clear_cmderr_if_set() this run.
175	  auto last_observed_cmderr() const -> uint32_t { return last_observed_cmderr_; }
176	  auto cmderr_clear_count() const -> uint64_t   { return cmderr_clear_count_; }
177	};
