179	// Read a 64-bit hart register (GPR / FPR / CSR by abstract regno) over DMI
180	// via an Abstract Command. Halts-and-reads contract: caller must have the
181	// hart in the halted state. Shared with StateDrain (drain at exit). If
182	// abstractcs.cmderr goes sticky after the command, the helper clears it and
183	// reports nullopt rather than blocking the caller -- a missing CSR mirrors as
184	// absent instead of corrupting the adjacent field.
185	inline auto read_register_64_checked(DmiBus& bus, uint16_t regno,
186	                                     const char* poll_label
187	                                       = "read_register_64")
188	  -> std::optional<uint64_t>
189	{
190	  using RD = ResumeDriver;
191	  bus.write(RD::kCommand,
192	            access_register_command(regno, AarSize::Bits64, /*write=*/false));
193	  poll_until_clear(bus, RD::kAbstractcs, RD::kAbstractcsBusy, poll_label);
194	  const auto status = bus.read(RD::kAbstractcs);
195	  if ((status & RD::kAbstractcsCmderrMask) != 0u) {
196	    bus.write(RD::kAbstractcs, RD::kAbstractcsCmderrMask);
197	    return std::nullopt;
198	  }
199	  const uint64_t lo = bus.read(RD::kData0);
200	  const uint64_t hi = bus.read(RD::kData1);
201	  return lo | (hi << 32);
202	}
203	
204	inline auto read_register_64(DmiBus& bus, uint16_t regno,
205	                             const char* poll_label = "read_register_64")
206	  -> uint64_t
207	{
208	  return read_register_64_checked(bus, regno, poll_label).value_or(0u);
209	}
