54	  // bit 9: allhalted, bit 17: allresumeack. Answering both lets the poll
55	  // loops finish on their first read. abstractcs reads return 0 (busy clear,
56	  // no cmderr), so each abstract write completes immediately.
57	  uint32_t dmstatus_value = 0;
