TEST_CASE("B17: cleared cmderr surfaces via diagnostic side-channel")
{
  // clear_cmderr_if_set() swallows any sticky cmderr left by an earlier
  // per-register abstract failure so the resume can still proceed. Without a
  // side channel that swallow is invisible. Pin the contract: when an
  // abstract write fails and no PB fallback absorbs it (here the DPC write,
  // the last abstract write before the tail clear), the driver records the
  // last observed non-zero cmderr and a non-zero clear count.
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);
  bus.fail_csr_write = 0x7B1;  // CSR DPC

  hybrid::ResumeDriver driver(bus);
  driver.resume(rv64_state(0x80001000, 0));

  CHECK(driver.cmderr_clear_count() > 0u);
  CHECK(driver.last_observed_cmderr() != 0u);
}

TEST_CASE("B9: write_csr_abstract_or_pb busy-poll precedes cmderr inspection")
{
  // Every abstract register write (write_register_abstract) busy-polls
  // abstractcs before returning, so by the time any caller inspects cmderr
  // the busy bit is already clear. Pin that contract: between each kCommand
  // write and the next, the recorded ops must include at least one
  // kAbstractcs read (the busy poll). A refactor that drops the chained poll
  // regresses this test.
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  hybrid::ResumeDriver driver(bus);
  driver.resume(rv64_state(0x80001000, 0xdeadbeef));

  bool saw_cmd = false;
  std::size_t reads_since_cmd = 0;
  bool all_cmds_had_abstractcs_poll = true;
  for (const auto& op : bus.ops) {
    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand) {
      if (saw_cmd && reads_since_cmd == 0)
        all_cmds_had_abstractcs_poll = false;
      saw_cmd = true;
      reads_since_cmd = 0;
    } else if (saw_cmd && op.kind == DmiOp::Kind::Read
               && op.reg == kAbstractcs) {
      ++reads_since_cmd;
    }
  }
  CHECK(all_cmds_had_abstractcs_poll);
  // The final kCommand write must also be followed by an abstractcs read.
  CHECK(reads_since_cmd > 0u);
}

